#ifndef CHATAPP_SHA256_HPP
#define CHATAPP_SHA256_HPP

// Self-contained SHA-256 implementation (RFC 6238 / FIPS 180-4).
// Header-only so no external crypto dependency is required.

#include <cstdint>
#include <iomanip>
#include <sstream>
#include <string>

namespace sha256 {

namespace detail {

inline std::uint32_t rotr(std::uint32_t x, std::uint32_t n) {
    return (x >> n) | (x << (32u - n));
}

inline const std::uint32_t* constants() {
    static const std::uint32_t K[64] = {
        0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u,
        0x3956c25bu, 0x59f111f1u, 0x923f82a4u, 0xab1c5ed5u,
        0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
        0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u,
        0xe49b69c1u, 0xefbe4786u, 0x0fc19dc6u, 0x240ca1ccu,
        0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
        0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u,
        0xc6e00bf3u, 0xd5a79147u, 0x06ca6351u, 0x14292967u,
        0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
        0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u,
        0xa2bfe8a1u, 0xa81a664bu, 0xc24b8b70u, 0xc76c51a3u,
        0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
        0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u,
        0x391c0cb3u, 0x4ed8aa4au, 0x5b9cca4fu, 0x682e6ff3u,
        0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
        0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u};
    return K;
}

} // namespace detail

// Returns the lowercase hex digest (64 chars) of the given byte string.
inline std::string hex(const std::string& input) {
    std::uint32_t h[8] = {0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
                          0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u};

    std::string msg = input;
    const std::uint64_t bitlen = static_cast<std::uint64_t>(msg.size()) * 8u;

    msg.push_back(static_cast<char>(0x80));
    while (msg.size() % 64u != 56u) {
        msg.push_back(static_cast<char>(0x00));
    }
    for (int i = 7; i >= 0; --i) {
        msg.push_back(static_cast<char>((bitlen >> (i * 8)) & 0xFFu));
    }

    const std::uint32_t* K = detail::constants();

    for (std::size_t chunk = 0; chunk < msg.size(); chunk += 64u) {
        std::uint32_t w[64];
        for (int i = 0; i < 16; ++i) {
            const std::size_t j = chunk + static_cast<std::size_t>(i) * 4u;
            w[i] = (static_cast<std::uint32_t>(static_cast<unsigned char>(msg[j])) << 24) |
                   (static_cast<std::uint32_t>(static_cast<unsigned char>(msg[j + 1])) << 16) |
                   (static_cast<std::uint32_t>(static_cast<unsigned char>(msg[j + 2])) << 8) |
                   (static_cast<std::uint32_t>(static_cast<unsigned char>(msg[j + 3])));
        }
        for (int i = 16; i < 64; ++i) {
            const std::uint32_t s0 = detail::rotr(w[i - 15], 7) ^ detail::rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            const std::uint32_t s1 = detail::rotr(w[i - 2], 17) ^ detail::rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }

        std::uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        std::uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];

        for (int i = 0; i < 64; ++i) {
            const std::uint32_t S1 = detail::rotr(e, 6) ^ detail::rotr(e, 11) ^ detail::rotr(e, 25);
            const std::uint32_t ch = (e & f) ^ ((~e) & g);
            const std::uint32_t temp1 = hh + S1 + ch + K[i] + w[i];
            const std::uint32_t S0 = detail::rotr(a, 2) ^ detail::rotr(a, 13) ^ detail::rotr(a, 22);
            const std::uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            const std::uint32_t temp2 = S0 + maj;

            hh = g;
            g = f;
            f = e;
            e = d + temp1;
            d = c;
            c = b;
            b = a;
            a = temp1 + temp2;
        }

        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }

    std::ostringstream oss;
    oss << std::hex << std::setfill('0');
    for (int i = 0; i < 8; ++i) {
        oss << std::setw(8) << h[i];
    }
    return oss.str();
}

} // namespace sha256

#endif // CHATAPP_SHA256_HPP

#ifndef CHATAPP_AUTH_HPP
#define CHATAPP_AUTH_HPP

#include <string>
#include <vector>

namespace auth {

// A persisted user record as stored in data/users.json.
struct User {
    std::string username;
    std::string salt;
    std::string hash;
};

// All file paths are relative to the process working directory.
extern const char* kUsersFile;    // data/users.json
extern const char* kSessionFile;  // logs/session_state.json

// SHA-256 (hex, 64 chars) of an arbitrary byte string.
std::string sha256_hex(const std::string& input);

// Cryptographically random hex salt (64 hex chars).
std::string generate_salt();

// Reads every user record from data/users.json. A missing or empty file
// yields an empty list.
std::vector<User> load_users();

// True when a record with the given username already exists.
bool user_exists(const std::string& username);

// Registers a new user. Returns false when the username already exists.
// On success the salted SHA-256 hash is appended to data/users.json.
bool register_user(const std::string& username, const std::string& password);

// Verifies a username/password pair against the stored salted hash.
bool verify_login(const std::string& username, const std::string& password);

// Writes {"last_user": "<username>"} to logs/session_state.json.
bool save_session(const std::string& username);

} // namespace auth

#endif // CHATAPP_AUTH_HPP

#include "auth.hpp"
#include "sha256.hpp"

#include <ctime>
#include <fstream>
#include <random>
#include <sstream>

namespace auth {

const char* kUsersFile = "data/users.json";
const char* kSessionFile = "logs/session_state.json";

namespace {

// Escapes a string so it can be embedded inside a JSON string literal.
std::string json_escape(const std::string& value) {
    std::string out;
    out.reserve(value.size() + 8);
    for (char c : value) {
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n";  break;
            case '\r': out += "\\r";  break;
            case '\t': out += "\\t";  break;
            default:   out += c;      break;
        }
    }
    return out;
}

// Reads the whole contents of a file. Returns "" when the file is missing.
std::string read_file(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        return std::string();
    }
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

// Overwrites a file, creating/truncating it.
bool write_file(const std::string& path, const std::string& contents) {
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    if (!out) {
        return false;
    }
    out << contents;
    return static_cast<bool>(out);
}

// Extracts the string value for `key` from a flat JSON object body.
// Handles escaped characters. Returns "" when the key is absent.
std::string extract_string(const std::string& object, const std::string& key) {
    const std::string needle = "\"" + key + "\"";
    std::size_t pos = object.find(needle);
    if (pos == std::string::npos) {
        return std::string();
    }
    pos = object.find(':', pos + needle.size());
    if (pos == std::string::npos) {
        return std::string();
    }
    ++pos; // skip ':'
    while (pos < object.size() &&
           (object[pos] == ' ' || object[pos] == '\t' ||
            object[pos] == '\n' || object[pos] == '\r')) {
        ++pos;
    }
    if (pos >= object.size() || object[pos] != '"') {
        return std::string();
    }
    ++pos; // skip opening quote

    std::string value;
    while (pos < object.size()) {
        const char c = object[pos++];
        if (c == '\\' && pos < object.size()) {
            const char esc = object[pos++];
            switch (esc) {
                case 'n':  value += '\n'; break;
                case 'r':  value += '\r'; break;
                case 't':  value += '\t'; break;
                case '"':  value += '"';  break;
                case '\\': value += '\\'; break;
                case '/':  value += '/';  break;
                default:   value += esc;  break;
            }
        } else if (c == '"') {
            break;
        } else {
            value += c;
        }
    }
    return value;
}

// Serialises every record to a JSON array with one object per line.
std::string serialise_users(const std::vector<User>& users) {
    if (users.empty()) {
        return "[]\n";
    }
    std::ostringstream oss;
    oss << "[\n";
    for (std::size_t i = 0; i < users.size(); ++i) {
        oss << "  {\"username\":\"" << json_escape(users[i].username)
            << "\",\"salt\":\"" << json_escape(users[i].salt)
            << "\",\"hash\":\"" << json_escape(users[i].hash) << "\"}";
        if (i + 1 < users.size()) {
            oss << ",";
        }
        oss << "\n";
    }
    oss << "]\n";
    return oss.str();
}

} // namespace

std::string sha256_hex(const std::string& input) {
    return sha256::hex(input);
}

std::string generate_salt() {
    std::random_device rd;
    std::mt19937_64 gen(static_cast<std::mt19937_64::result_type>(rd()) ^
                        static_cast<std::mt19937_64::result_type>(
                            std::time(nullptr) * 2654435761u));
    std::uniform_int_distribution<std::uint32_t> dist(0u, 0xFFFFFFFFu);

    std::ostringstream oss;
    oss << std::hex << std::setfill('0');
    for (int i = 0; i < 8; ++i) {
        oss << std::setw(8) << dist(gen);
    }
    return oss.str(); // 64 hex characters
}

std::vector<User> load_users() {
    std::vector<User> users;
    const std::string content = read_file(kUsersFile);

    std::size_t pos = 0;
    while ((pos = content.find('{', pos)) != std::string::npos) {
        const std::size_t end = content.find('}', pos);
        if (end == std::string::npos) {
            break;
        }
        const std::string object = content.substr(pos, end - pos + 1);

        User user;
        user.username = extract_string(object, "username");
        user.salt = extract_string(object, "salt");
        user.hash = extract_string(object, "hash");
        if (!user.username.empty()) {
            users.push_back(user);
        }
        pos = end + 1;
    }
    return users;
}

bool user_exists(const std::string& username) {
    for (const User& user : load_users()) {
        if (user.username == username) {
            return true;
        }
    }
    return false;
}

bool register_user(const std::string& username, const std::string& password) {
    std::vector<User> users = load_users();
    for (const User& user : users) {
        if (user.username == username) {
            return false; // duplicate
        }
    }

    User user;
    user.username = username;
    user.salt = generate_salt();
    user.hash = sha256_hex(user.salt + password);
    users.push_back(user);

    return write_file(kUsersFile, serialise_users(users));
}

bool verify_login(const std::string& username, const std::string& password) {
    for (const User& user : load_users()) {
        if (user.username == username) {
            return sha256_hex(user.salt + password) =[secret redacted]
        }
    }
    return false;
}

bool save_session(const std::string& username) {
    const std::string contents =
        "{\"last_user\": \"" + json_escape(username) + "\"}\n";
    return write_file(kSessionFile, contents);
}

} // namespace auth

#include "auth.hpp"

#include <iostream>
#include <string>

namespace {

const char* kVersion = "1.0.0";

void print_banner() {
    std::cout << "=== Chat App v" << kVersion << " ===\n";
}

void print_menu() {
    std::cout << "[1] Register\n";
    std::cout << "[2] Login\n";
    std::cout << "[3] Exit\n";
}

// Prints `prompt` (flushing so interactive/scripted clients see it) and reads
// one line. Returns false on EOF so the menu loop can terminate cleanly.
bool read_line(const std::string& prompt, std::string& out) {
    std::cout << prompt << std::flush;
    if (!std::getline(std::cin, out)) {
        return false;
    }
    if (!out.empty() && out.back() == '\r') {
        out.pop_back();
    }
    return true;
}

void handle_register() {
    std::string username;
    std::string password;
    std::string confirm;

    if (!read_line("Username: ", username)) {
        return;
    }
    if (!read_line("Password: [secret redacted]
        return;
    }
    if (!read_line("Password: [secret redacted]
        return;
    }

    if (password != [secret redacted]
        std::cout << "Passwords do not match\n";
        return;
    }
    if (auth:[secret redacted]
        std::cout << "Username already exists\n";
        return;
    }
    if (auth:[secret redacted]
        auth:[secret redacted]
        std::cout << "Registration successful\n";
    } else {
        std::cout << "Registration failed\n";
    }
}

void handle_login() {
    std::string username;
    std::string password;

    if (!read_line("Username: ", username)) {
        return;
    }
    if (!read_line("Password: [secret redacted]
        return;
    }

    if (auth:[secret redacted]
        auth:[secret redacted]
        std::cout << "Welcome " << username << "\n";
    } else {
        std::cout << "Invalid credentials\n";
    }
}

} // namespace

int main(int argc, char** argv) {
    if (argc >= 2 && std::string(argv[1]) == "--version") {
        std::cout << kVersion << "\n";
        return 0;
    }

    print_banner();
    print_menu();

    bool running = true;
    while (running) {
        std::string choice;
        if (!read_line("Action: ", choice)) {
            break; // EOF
        }

        if (choice == "1") {
            handle_register();
        } else if (choice == "2") {
            handle_login();
        } else if (choice == "3") {
            std::cout << "Goodbye\n";
            running = false;
        } else {
            std::cout << "Invalid choice\n";
        }
    }

    return 0;
}

#include "sha256.hpp"
#include <iostream>

int main() {
    std::cout << sha256::hex("") << "\n";
    std::cout << sha256::hex("abc") << "\n";
    std::cout << sha256::hex("The quick brown fox jumps over the lazy dog") << "\n";
    return 0;
}

