#ifndef CHATAPP_JSON_UTIL_HPP
#define CHATAPP_JSON_UTIL_HPP

// Small shared helpers for reading/writing the simple flat JSON stores used by
// the chat app (data/users.json, data/friends_<user>.json, ...).

#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>

namespace jsonutil {

// Ensures the parent directory of `path` exists (best effort).
inline void ensure_parent_dir(const std::string& path) {
    const std::size_t slash = path.find_last_of("/\\");
    if (slash == std::string::npos) {
        return;
    }
    std::error_code ec;
    std::filesystem::create_directories(path.substr(0, slash), ec);
}

// Escapes a string so it can be embedded inside a JSON string literal.
inline std::string escape(const std::string& value) {
    std::string out;
    out.reserve(value.size() + 8);
    for (char c : value) {
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n";  break;
            case '\r': out += "\\r";  break;
            case '\t': out += "\\t";  break;
            default:   out += c;      break;
        }
    }
    return out;
}

// Reads the whole contents of a file. Returns "" when the file is missing.
inline std::string read_file(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        return std::string();
    }
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

// Overwrites a file, creating/truncating it and its parent directory.
inline bool write_file(const std::string& path, const std::string& contents) {
    ensure_parent_dir(path);
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    if (!out) {
        return false;
    }
    out << contents;
    return static_cast<bool>(out);
}

// Extracts the string value for `key` from a flat JSON object body.
// Handles escaped characters. Returns "" when the key is absent.
inline std::string extract_string(const std::string& object, const std::string& key) {
    const std::string needle = "\"" + key + "\"";
    std::size_t pos = object.find(needle);
    if (pos == std::string::npos) {
        return std::string();
    }
    pos = object.find(':', pos + needle.size());
    if (pos == std::string::npos) {
        return std::string();
    }
    ++pos; // skip ':'
    while (pos < object.size() &&
           (object[pos] == ' ' || object[pos] == '\t' ||
            object[pos] == '\n' || object[pos] == '\r')) {
        ++pos;
    }
    if (pos >= object.size() || object[pos] != '"') {
        return std::string();
    }
    ++pos; // skip opening quote

    std::string value;
    while (pos < object.size()) {
        const char c = object[pos++];
        if (c == '\\' && pos < object.size()) {
            const char esc = object[pos++];
            switch (esc) {
                case 'n':  value += '\n'; break;
                case 'r':  value += '\r'; break;
                case 't':  value += '\t'; break;
                case '"':  value += '"';  break;
                case '\\': value += '\\'; break;
                case '/':  value += '/';  break;
                default:   value += esc;  break;
            }
        } else if (c == '"') {
            break;
        } else {
            value += c;
        }
    }
    return value;
}

// Iterates the flat objects `{...}` inside a JSON array body, invoking `fn`
// with each object's text. Braces inside strings are handled.
template <typename Fn>
inline void for_each_object(const std::string& content, Fn fn) {
    std::size_t pos = 0;
    while ((pos = content.find('{', pos)) != std::string::npos) {
        std::size_t i = pos + 1;
        bool in_string = false;
        bool escaped = false;
        std::size_t end = std::string::npos;
        for (; i < content.size(); ++i) {
            const char c = content[i];
            if (in_string) {
                if (escaped) {
                    escaped = false;
                } else if (c == '\\') {
                    escaped = true;
                } else if (c == '"') {
                    in_string = false;
                }
            } else if (c == '"') {
                in_string = true;
            } else if (c == '}') {
                end = i;
                break;
            }
        }
        if (end == std::string::npos) {
            break;
        }
        fn(content.substr(pos, end - pos + 1));
        pos = end + 1;
    }
}

} // namespace jsonutil

#endif // CHATAPP_JSON_UTIL_HPP

#ifndef CHATAPP_FRIENDS_HPP
#define CHATAPP_FRIENDS_HPP

#include <string>
#include <vector>

namespace friends {

// A persisted friend record as stored in data/friends_<username>.json.
struct Friend {
    std::string user;
    std::string status; // "online" or "offline"
};

// Returns the on-disk path for a user's friend store.
std::string friends_path(const std::string& username);

// Loads the friend list for `username`. A missing/empty file yields an empty
// list and every record's status defaults to "offline" when absent.
std::vector<Friend> load_friends(const std::string& username);

// Persists the full friend list for `username`.
bool save_friends(const std::string& username, const std::vector<Friend>& list);

// True when `friendName` is already in `username`'s list.
bool friend_exists(const std::string& username, const std::string& friendName);

// Adds a friend with status "offline". Returns false if already present.
bool add_friend(const std::string& username, const std::string& friendName);

// Removes a friend. Returns false when the friend was not present.
bool remove_friend(const std::string& username, const std::string& friendName);

} // namespace friends

#endif // CHATAPP_FRIENDS_HPP

#include "friends.hpp"
#include "json_util.hpp"

#include <sstream>

namespace friends {

std::string friends_path(const std::string& username) {
    return "data/friends_" + username + ".json";
}

std::vector<Friend> load_friends(const std::string& username) {
    std::vector<Friend> result;
    const std::string content = jsonutil::read_file(friends_path(username));

    jsonutil::for_each_object(content, [&result](const std::string& object) {
        Friend f;
        f.user = jsonutil::extract_string(object, "user");
        f.status = jsonutil::extract_string(object, "status");
        if (f.status != "online" && f.status != "offline") {
            f.status = "offline"; // default
        }
        if (!f.user.empty()) {
            result.push_back(f);
        }
    });

    return result;
}

bool save_friends(const std::string& username, const std::vector<Friend>& list) {
    std::ostringstream oss;
    oss << "[";
    if (!list.empty()) {
        oss << "\n";
        for (std::size_t i = 0; i < list.size(); ++i) {
            oss << "  {\"user\": \"" << jsonutil::escape(list[i].user)
                << "\", \"status\": \"" << jsonutil::escape(list[i].status) << "\"}";
            if (i + 1 < list.size()) {
                oss << ",";
            }
            oss << "\n";
        }
    }
    oss << "]\n";

    return jsonutil::write_file(friends_path(username), oss.str());
}

bool friend_exists(const std::string& username, const std::string& friendName) {
    for (const Friend& f : load_friends(username)) {
        if (f.user == friendName) {
            return true;
        }
    }
    return false;
}

bool add_friend(const std::string& username, const std::string& friendName) {
    std::vector<Friend> list = load_friends(username);
    for (const Friend& f : list) {
        if (f.user == friendName) {
            return false; // duplicate
        }
    }

    Friend f;
    f.user = friendName;
    f.status = "offline"; // default status
    list.push_back(f);

    return save_friends(username, list);
}

bool remove_friend(const std::string& username, const std::string& friendName) {
    std::vector<Friend> list = load_friends(username);

    std::vector<Friend> kept;
    kept.reserve(list.size());
    bool removed = false;
    for (const Friend& f : list) {
        if (f.user == friendName) {
            removed = true;
            continue;
        }
        kept.push_back(f);
    }

    if (!removed) {
        return false;
    }
    return save_friends(username, kept);
}

} // namespace friends

