#include "auth.hpp"
#include "json_util.hpp"
#include "sha256.hpp"

#include <ctime>
#include <random>
#include <sstream>

namespace auth {

const char* kUsersFile = "data/users.json";
const char* kSessionFile = "logs/session_state.json";

namespace {

// Serialises every record to a JSON array with one object per line.
std::string serialise_users(const std::vector<User>& users) {
    if (users.empty()) {
        return "[]\n";
    }
    std::ostringstream oss;
    oss << "[\n";
    for (std::size_t i = 0; i < users.size(); ++i) {
        oss << "  {\"username\":\"" << jsonutil::escape(users[i].username)
            << "\",\"salt\":\"" << jsonutil::escape(users[i].salt)
            << "\",\"hash\":\"" << jsonutil::escape(users[i].hash) << "\"}";
        if (i + 1 < users.size()) {
            oss << ",";
        }
        oss << "\n";
    }
    oss << "]\n";
    return oss.str();
}

} // namespace

std::string sha256_hex(const std::string& input) {
    return sha256::hex(input);
}

std::string generate_salt() {
    std::random_device rd;
    std::mt19937_64 gen(static_cast<std::mt19937_64::result_type>(rd()) ^
                        static_cast<std::mt19937_64::result_type>(
                            std::time(nullptr) * 2654435761u));
    std::uniform_int_distribution<std::uint32_t> dist(0u, 0xFFFFFFFFu);

    std::ostringstream oss;
    oss << std::hex << std::setfill('0');
    for (int i = 0; i < 8; ++i) {
        oss << std::setw(8) << dist(gen);
    }
    return oss.str(); // 64 hex characters
}

std::vector<User> load_users() {
    std::vector<User> users;
    const std::string content = jsonutil::read_file(kUsersFile);

    jsonutil::for_each_object(content, [&users](const std::string& object) {
        User user;
        user.username = jsonutil::extract_string(object, "username");
        user.salt = jsonutil::extract_string(object, "salt");
        user.hash = jsonutil::extract_string(object, "hash");
        if (!user.username.empty()) {
            users.push_back(user);
        }
    });

    return users;
}

bool user_exists(const std::string& username) {
    for (const User& user : load_users()) {
        if (user.username == username) {
            return true;
        }
    }
    return false;
}

bool register_user(const std::string& username, const std::string& password) {
    std::vector<User> users = load_users();
    for (const User& user : users) {
        if (user.username == username) {
            return false; // duplicate
        }
    }

    User user;
    user.username = username;
    user.salt = generate_salt();
    user.hash = sha256_hex(user.salt + password);
    users.push_back(user);

    return jsonutil::write_file(kUsersFile, serialise_users(users));
}

bool verify_login(const std::string& username, const std::string& password) {
    for (const User& user : load_users()) {
        if (user.username == username) {
            return sha256_hex(user.salt + password) =[secret redacted]
        }
    }
    return false;
}

bool save_session(const std::string& username) {
    const std::string contents =
        "{\"last_user\": \"" + jsonutil::escape(username) + "\"}\n";
    return jsonutil::write_file(kSessionFile, contents);
}

std::string load_session_user() {
    const std::string content = jsonutil::read_file(kSessionFile);
    return jsonutil::extract_string(content, "last_user");
}

} // namespace auth

#include "auth.hpp"
#include "friends.hpp"
#include "json_util.hpp"

#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>

namespace {

const char* kVersion = "1.0.0";

void print_banner() {
    std::cout << "=== Chat App v" << kVersion << " ===\n";
}

void print_auth_menu() {
    std::cout << "[1] Register\n";
    std::cout << "[2] Login\n";
    std::cout << "[3] Exit\n";
}

void print_friend_menu() {
    std::cout << "[A] Add Friend\n";
    std::cout << "[R] Remove Friend\n";
    std::cout << "[L] List Friends\n";
    std::cout << "[C] Choose Friend\n";
    std::cout << "[Q] Logout\n";
}

// Prints `prompt` (flushing so interactive/scripted clients see it) and reads
// one line. Returns false on EOF so the menu loop can terminate cleanly.
bool read_line(const std::string& prompt, std::string& out) {
    std::cout << prompt << std::flush;
    if (!std::getline(std::cin, out)) {
        return false;
    }
    if (!out.empty() && out.back() == '\r') {
        out.pop_back();
    }
    return true;
}

// ---------------------------------------------------------------- auth flow

void handle_register() {
    std::string username;
    std::string password;
    std::string confirm;

    if (!read_line("Username: ", username)) {
        return;
    }
    if (!read_line("Password: [secret redacted]
        return;
    }
    if (!read_line("Password: [secret redacted]
        return;
    }

    if (password != [secret redacted]
        std::cout << "Passwords do not match\n";
        return;
    }
    if (auth:[secret redacted]
        std::cout << "Username already exists\n";
        return;
    }
    if (auth:[secret redacted]
        auth:[secret redacted]
        std::cout << "Registration successful\n";
    } else {
        std::cout << "Registration failed\n";
    }
}

// Returns 1 on success, 0 on bad credentials, -1 on EOF.
int handle_login(std::string& current_user) {
    std::string username;
    std::string password;

    if (!read_line("Username: ", username)) {
        return -1;
    }
    if (!read_line("Password: [secret redacted]
        return -1;
    }

    if (auth:[secret redacted]
        auth:[secret redacted]
        current_user = username;
        std::cout << "Welcome " << username << "\n";
        return 1;
    }

    std::cout << "Invalid credentials\n";
    return 0;
}

// -------------------------------------------------------------- friend flow

void list_friends(const std::string& owner) {
    for (const friends::Friend& f : friends::load_friends(owner)) {
        std::cout << "  - " << f.user << " [" << f.status << "]\n";
    }
}

void handle_add_friend(const std::string& owner) {
    std::string name;
    if (!read_line("Friend: ", name)) {
        return;
    }
    if (name.empty()) {
        std::cout << "Invalid friend name\n";
        return;
    }
    if (friends::friend_exists(owner, name)) {
        std::cout << "Friend already exists\n";
        return;
    }
    if (friends::add_friend(owner, name)) {
        std::cout << "Friend added\n";
    } else {
        std::cout << "Failed to add friend\n";
    }
}

void handle_remove_friend(const std::string& owner) {
    std::string name;
    if (!read_line("Friend: ", name)) {
        return;
    }
    if (friends::remove_friend(owner, name)) {
        std::cout << "Friend removed\n";
    } else {
        std::cout << "Friend not found\n";
    }
}

void handle_choose_friend(const std::string& owner) {
    std::string id;
    if (!read_line("Friend: ", id)) {
        return;
    }

    const std::vector<friends::Friend> list = friends::load_friends(owner);

    std::string target;
    for (const friends::Friend& f : list) {
        if (f.user == id) {
            target = f.user;
            break;
        }
    }
    // Also accept a 1-based index into the friend list ("friend ID").
    if (target.empty()) {
        char* endp = nullptr;
        const long index = std::strtol(id.c_str(), &endp, 10);
        if (endp != id.c_str() && *endp == '\0' &&
            index >= 1 && index <= static_cast<long>(list.size())) {
            target = list[static_cast<std::size_t>(index - 1)].user;
        }
    }

    if (target.empty()) {
        std::cout << "Friend not found\n";
        return;
    }

    std::cout << "--- Chat with " << target << " ---\n";
    std::string message;
    while (read_line("> ", message)) {
        if (message == "/back") {
            break;
        }
        // Baseline chat: no message persistence yet.
    }
}

void handle_friend_action(const std::string& owner, const std::string& choice) {
    if (choice == "A" || choice == "a") {
        handle_add_friend(owner);
    } else if (choice == "R" || choice == "r") {
        handle_remove_friend(owner);
    } else if (choice == "L" || choice == "l") {
        list_friends(owner);
    } else if (choice == "C" || choice == "c") {
        handle_choose_friend(owner);
    } else {
        std::cout << "Invalid choice\n";
    }
}

// ------------------------------------------------------------- friend-menu

int selftest_friend_menu() {
    const std::string user = auth::load_session_user();
    const std::vector<friends::Friend> list = friends::load_friends(user);

    std::cout << "{\"user\": \"" << jsonutil::escape(user) << "\", \"friends\": [";
    for (std::size_t i = 0; i < list.size(); ++i) {
        std::cout << "{\"user\": \"" << jsonutil::escape(list[i].user)
                  << "\", \"status\": \"" << jsonutil::escape(list[i].status) << "\"}";
        if (i + 1 < list.size()) {
            std::cout << ", ";
        }
    }
    std::cout << "]}\n";
    return 0;
}

} // namespace

int main(int argc, char** argv) {
    if (argc >= 2 && std::string(argv[1]) == "--version") {
        std::cout << kVersion << "\n";
        return 0;
    }
    if (argc >= 3 && std::string(argv[1]) == "--selftest" &&
        std::string(argv[2]) == "friend-menu") {
        return selftest_friend_menu();
    }

    print_banner();
    print_auth_menu();

    std::string current_user;
    bool running = true;
    while (running) {
        std::string choice;
        if (!read_line("Action: ", choice)) {
            break; // EOF
        }

        if (current_user.empty()) {
            // Logged-out menu.
            if (choice == "1") {
                handle_register();
            } else if (choice == "2") {
                const int result = handle_login(current_user);
                if (result < 0) {
                    break;
                }
                if (result > 0) {
                    print_friend_menu();
                }
            } else if (choice == "3") {
                std::cout << "Goodbye\n";
                running = false;
            } else {
                std::cout << "Invalid choice\n";
            }
        } else {
            // Logged-in friend menu.
            if (choice == "Q" || choice == "q") {
                current_user.clear();
                std::cout << "Logged out\n";
                print_auth_menu();
            } else {
                handle_friend_action(current_user, choice);
            }
        }
    }

    return 0;
}

