#ifndef CHATAPP_CHAT_HPP
#define CHATAPP_CHAT_HPP

#include <string>
#include <vector>

namespace chat {

// One stored transcript entry.
struct Message {
    std::string timestamp; // ISO 8601, e.g. 2026-10-10T12:34:56
    std::string sender;    // username or "Bot"
    std::string text;
};

// Current local time formatted as YYYY-MM-DDTHH:MM:SS.
std::string now_iso8601();

// data/history/<user>/<friend>.log
std::string history_path(const std::string& user, const std::string& friendName);

// Loads the bot reply pool from data/scripts/bot_replies.json (array of
// strings). Falls back to a single reply when the file is missing.
std::vector<std::string> load_bot_replies();

// Appends one transcript line in `<ISO8601> | <sender> | <text>` format.
bool append_history(const std::string& user, const std::string& friendName,
                    const std::string& sender, const std::string& text);

// Reads the transcript in chronological (oldest-first) order.
std::vector<Message> load_history(const std::string& user, const std::string& friendName);

// Truncates the transcript for this user/friend pair.
bool clear_history(const std::string& user, const std::string& friendName);

// Prints one page of history (page 1 = newest 10 entries) to stdout.
void print_history(const std::string& user, const std::string& friendName, int page);

// Interactive single-friend chat loop (prompt "> "). Returns on /exit or /back.
void run_chat(const std::string& user, const std::string& friendName);

// Simulates 3 turns (User-Bot-User) and returns a JSON log string.
std::string selftest_chat_loop();

} // namespace chat

#endif // CHATAPP_CHAT_HPP

#include "chat.hpp"
#include "auth.hpp"
#include "json_util.hpp"

#include <cstdlib>
#include <ctime>
#include <fstream>
#include <iostream>
#include <sstream>

namespace chat {

namespace {

// Parses a JSON array of strings (used by bot_replies.json).
std::vector<std::string> parse_string_array(const std::string& content) {
    std::vector<std::string> out;
    std::size_t i = 0;
    while (i < content.size()) {
        if (content[i] != '"') {
            ++i;
            continue;
        }
        ++i; // opening quote
        std::string value;
        while (i < content.size()) {
            const char c = content[i++];
            if (c == '\\' && i < content.size()) {
                const char esc = content[i++];
                switch (esc) {
                    case 'n':  value += '\n'; break;
                    case 'r':  value += '\r'; break;
                    case 't':  value += '\t'; break;
                    case '"':  value += '"';  break;
                    case '\\': value += '\\'; break;
                    case '/':  value += '/';  break;
                    default:   value += esc;  break;
                }
            } else if (c == '"') {
                break;
            } else {
                value += c;
            }
        }
        out.push_back(value);
    }
    return out;
}

std::string trim(const std::string& s) {
    const std::size_t first = s.find_first_not_of(" \t");
    if (first == std::string::npos) {
        return std::string();
    }
    const std::size_t last = s.find_last_not_of(" \t");
    return s.substr(first, last - first + 1);
}

} // namespace

std::string now_iso8601() {
    const std::time_t now = std::time(nullptr);
    std::tm tmv{};
#if defined(_WIN32)
    localtime_s(&tmv, &now);
#else
    localtime_r(&now, &tmv);
#endif
    char buffer[32];
    std::strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &tmv);
    return std::string(buffer);
}

std::string history_path(const std::string& user, const std::string& friendName) {
    return "data/history/" + user + "/" + friendName + ".log";
}

std::vector<std::string> load_bot_replies() {
    const std::string content = jsonutil::read_file("data/scripts/bot_replies.json");
    std::vector<std::string> replies = parse_string_array(content);
    if (replies.empty()) {
        replies.push_back("Hello!");
    }
    return replies;
}

bool append_history(const std::string& user, const std::string& friendName,
                    const std::string& sender, const std::string& text) {
    const std::string path = history_path(user, friendName);
    jsonutil::ensure_parent_dir(path);

    std::ofstream out(path, std::ios::binary | std::ios::app);
    if (!out) {
        return false;
    }
    out << now_iso8601() << " | " << sender << " | " << text << "\n";
    return static_cast<bool>(out);
}

std::vector<Message> load_history(const std::string& user, const std::string& friendName) {
    std::vector<Message> messages;
    const std::string content = jsonutil::read_file(history_path(user, friendName));

    std::istringstream iss(content);
    std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
        if (line.empty()) {
            continue;
        }
        const std::size_t p1 = line.find(" | ");
        if (p1 == std::string::npos) {
            continue;
        }
        const std::size_t p2 = line.find(" | ", p1 + 3);
        if (p2 == std::string::npos) {
            continue;
        }
        Message m;
        m.timestamp = line.substr(0, p1);
        m.sender = line.substr(p1 + 3, p2 - (p1 + 3));
        m.text = line.substr(p2 + 3);
        messages.push_back(m);
    }
    return messages;
}

bool clear_history(const std::string& user, const std::string& friendName) {
    return jsonutil::write_file(history_path(user, friendName), std::string());
}

void print_history(const std::string& user, const std::string& friendName, int page) {
    if (page < 1) {
        page = 1;
    }
    const std::vector<Message> messages = load_history(user, friendName);
    const int total = static_cast<int>(messages.size());
    const int start = (page - 1) * 10; // newest-first index

    for (int i = start; i < start + 10 && i < total; ++i) {
        const Message& m = messages[static_cast<std::size_t>(total - 1 - i)];
        std::cout << m.timestamp << " | " << m.sender << " | " << m.text << "\n";
    }
}

void run_chat(const std::string& user, const std::string& friendName) {
    const std::vector<std::string> replies = load_bot_replies();
    std::size_t replyIndex = 0;

    std::string line;
    while (true) {
        std::cout << "> " << std::flush;
        if (!std::getline(std::cin, line)) {
            break; // EOF
        }
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }

        if (line == "/exit" || line == "/back") {
            return;
        }

        if (line == "/history" || line.rfind("/history ", 0) == 0) {
            const std::string arg = trim(line.substr(line.find(' ') == std::string::npos
                                                       ? line.size()
                                                       : line.find(' ') + 1));
            const int page = arg.empty() ? 1 : std::atoi(arg.c_str());
            print_history(user, friendName, page);
            continue;
        }

        if (line == "/clear") {
            clear_history(user, friendName);
            std::cout << "History cleared\n";
            continue;
        }

        if (line.empty()) {
            continue;
        }

        // Normal message: persist it, then emit the next bot reply immediately.
        append_history(user, friendName, user, line);

        const std::string reply = replies[replyIndex % replies.size()];
        ++replyIndex;
        append_history(user, friendName, "Bot", reply);

        std::cout << "[Bot] " << reply << "\n";
    }
}

std::string selftest_chat_loop() {
    const std::vector<std::string> replies = load_bot_replies();
    const std::string reply = replies.front();

    std::string user = auth::load_session_user();
    if (user.empty()) {
        user = "user";
    }

    struct Turn {
        std::string sender;
        std::string text;
    };
    const std::vector<Turn> turns = {
        {user, "Hello"},
        {"Bot", reply},
        {user, "Thanks!"},
    };

    std::ostringstream oss;
    oss << "{ \"messages\": [";
    for (std::size_t i = 0; i < turns.size(); ++i) {
        oss << "{ \"sender\": \"" << jsonutil::escape(turns[i].sender)
            << "\", \"text\": \"" << jsonutil::escape(turns[i].text)
            << "\", \"timestamp\": \"" << now_iso8601() << "\" }";
        if (i + 1 < turns.size()) {
            oss << ", ";
        }
    }
    oss << "] }";
    return oss.str();
}

} // namespace chat

