#ifndef CHATAPP_ALIAS_HPP
#define CHATAPP_ALIAS_HPP

#include <string>
#include <vector>

namespace alias {

// One friend -> alias mapping.
struct Entry {
    std::string friendName;
    std::string aliasName;
};

// data/aliases_<user>.json
std::string aliases_path(const std::string& user);

// Loads the alias map for `user` (JSON object of friend -> alias).
std::vector<Entry> load_aliases(const std::string& user);

// Returns the alias for `friendName`, or "" when none is set.
std::string get_alias(const std::string& user, const std::string& friendName);

// Returns the alias when set, otherwise the friend name - the name to show in
// headers, friend lists and search results.
std::string display_name(const std::string& user, const std::string& friendName);

// Stores (or updates) an alias. Returns false on write failure.
bool set_alias(const std::string& user, const std::string& friendName,
               const std::string& aliasName);

// Removes an alias if present.
bool remove_alias(const std::string& user, const std::string& friendName);

} // namespace alias

#endif // CHATAPP_ALIAS_HPP

#include "alias.hpp"
#include "json_util.hpp"

#include <sstream>
#include <utility>

namespace alias {

namespace {

// Parses a flat JSON object into ordered key/value pairs, handling escapes.
std::vector<std::pair<std::string, std::string>> parse_map(const std::string& content) {
    std::vector<std::pair<std::string, std::string>> pairs;
    std::size_t i = 0;
    while (i < content.size()) {
        const std::size_t keyStart = content.find('"', i);
        if (keyStart =[secret redacted]
            break;
        }

        std::string key;
        std::size_t j = keyStart + 1;
        bool keyClosed = [secret redacted]
        while (j < content.size()) {
            const char c = content[j++];
            if (c == '\\' && j < content.size()) {
                key += [secret redacted]
            } else if (c == '"') {
                keyClosed = [secret redacted]
                break;
            } else {
                key += [secret redacted]
            }
        }
        if (!keyClosed) {
            break;
        }

        const std::size_t colon = content.find(':', j);
        if (colon == std::string::npos) {
            break;
        }
        const std::size_t valStart = content.find('"', colon + 1);
        if (valStart == std::string::npos) {
            break;
        }

        std::string value;
        std::size_t m = valStart + 1;
        bool valClosed = false;
        while (m < content.size()) {
            const char c = content[m++];
            if (c == '\\' && m < content.size()) {
                value += content[m++];
            } else if (c == '"') {
                valClosed = true;
                break;
            } else {
                value += c;
            }
        }
        if (!valClosed) {
            break;
        }

        pairs.emplace_back(key, value);
        i = m;
    }
    return pairs;
}

std::string serialise(const std::vector<Entry>& entries) {
    std::ostringstream oss;
    oss << "{";
    for (std::size_t i = 0; i < entries.size(); ++i) {
        oss << "\"" << jsonutil::escape(entries[i].friendName) << "\": \""
            << jsonutil::escape(entries[i].aliasName) << "\"";
        if (i + 1 < entries.size()) {
            oss << ", ";
        }
    }
    oss << "}\n";
    return oss.str();
}

} // namespace

std::string aliases_path(const std::string& user) {
    return "data/aliases_" + user + ".json";
}

std::vector<Entry> load_aliases(const std::string& user) {
    std::vector<Entry> entries;
    const std::string content = jsonutil::read_file(aliases_path(user));
    for (const auto& pair : parse_map(content)) {
        Entry e;
        e.friendName = pair.first;
        e.aliasName = pair.second;
        if (!e.friendName.empty()) {
            entries.push_back(e);
        }
    }
    return entries;
}

std::string get_alias(const std::string& user, const std::string& friendName) {
    for (const Entry& e : load_aliases(user)) {
        if (e.friendName == friendName) {
            return e.aliasName;
        }
    }
    return std::string();
}

std::string display_name(const std::string& user, const std::string& friendName) {
    const std::string a = get_alias(user, friendName);
    return a.empty() ? friendName : a;
}

bool set_alias(const std::string& user, const std::string& friendName,
               const std::string& aliasName) {
    std::vector<Entry> entries = load_aliases(user);
    bool updated = false;
    for (Entry& e : entries) {
        if (e.friendName == friendName) {
            e.aliasName = aliasName;
            updated = true;
            break;
        }
    }
    if (!updated) {
        Entry e;
        e.friendName = friendName;
        e.aliasName = aliasName;
        entries.push_back(e);
    }
    return jsonutil::write_file(aliases_path(user), serialise(entries));
}

bool remove_alias(const std::string& user, const std::string& friendName) {
    std::vector<Entry> entries = load_aliases(user);
    std::vector<Entry> kept;
    kept.reserve(entries.size());
    bool removed = false;
    for (const Entry& e : entries) {
        if (e.friendName == friendName) {
            removed = true;
            continue;
        }
        kept.push_back(e);
    }
    if (!removed) {
        return false;
    }
    return jsonutil::write_file(aliases_path(user), serialise(kept));
}

} // namespace alias

#ifndef CHATAPP_SEARCH_HPP
#define CHATAPP_SEARCH_HPP

#include <string>
#include <vector>

namespace search {

// One matching transcript line.
struct Result {
    std::string friendName; // owner of the log file
    std::string date;       // ISO 8601 timestamp from the line
    std::string text;       // full message text
    std::string snippet;    // text with the match wrapped in [[...]]
};

// Case-insensitively searches every log under data/history/<user>/ .
std::vector<Result> search_all(const std::string& user, const std::string& keyword);

// Builds a `...context[[match]]context...` snippet around the first
