std::string to_lower(const std::string& s) {
    std::string out = s;
    for (char& c : out) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return out;
}

} // namespace

std::string highlight(const std::string& text, const std::string& keyword) {
    if (keyword.empty()) {
        return text;
    }
    const std::string lowerText = to_lower(text);
    const std::string lowerKey = to_lower(keyword);
    const std::size_t pos = lowerText.find(lowerKey);
    if (pos == std::string::npos) {
        return text;
    }

    const std::size_t klen = keyword.size();
    const std::size_t ctx = 20;
    const std::size_t start = pos > ctx ? pos - ctx : 0;
    const std::size_t end = std::min(text.size(), pos + klen + ctx);

    std::string out;
    if (start > 0) {
        out += "...";
    }
    out += text.substr(start, pos - start);
    out += "[[";
    out += text.substr(pos, klen);
    out += "]]";
    out += text.substr(pos + klen, end - (pos + klen));
    if (end < text.size()) {
        out += "...";
    }
    return out;
}

std::vector<Result> search_all(const std::string& user, const std::string& keyword) {
    std::vector<Result> results;
    if (keyword.empty()) {
        return results;
    }

    const std::string dir = "data/history/" + user;
    std::error_code ec;
    if (!std::filesystem::is_directory(dir, ec)) {
        return results;
    }

    std::vector<std::string> files;
    for (const auto& entry : std::filesystem::directory_iterator(dir, ec)) {
        if (entry.is_regular_file(ec) && entry.path().extension() == ".log") {
            files.push_back(entry.path().string());
        }
    }
    std::sort(files.begin(), files.end());

    const std::string lowerKey = to_lower(keyword);

    for (const std::string& file : files) {
        const std::string friendName = std::filesystem::path(file).stem().string();
        const std::string content = jsonutil::read_file(file);

        std::istringstream iss(content);
        std::string line;
        while (std::getline(iss, line)) {
            if (!line.empty() && line.back() == '\r') {
                line.pop_back();
            }
            if (line.empty()) {
                continue;
            }
            const std::size_t p1 = line.find(" | ");
            if (p1 == std::string::npos) {
                continue;
            }
            const std::size_t p2 = line.find(" | ", p1 + 3);
            if (p2 == std::string::npos) {
                continue;
            }

            Result r;
            r.friendName = friendName;
            r.date = line.substr(0, p1);
            r.text = line.substr(p2 + 3);

            if (to_lower(r.text).find(lowerKey) != [secret redacted]
                r.snippet = highlight(r.text, keyword);
                results.push_back(r);
            }
        }
    }

    return results;
}

} // namespace search

