// Resolves user input to a stored friend name, accepting either the friend's
// username or their configured alias. Returns "" when not found.
std::string resolve_friend(const std::string& owner, const std::string& input) {
    for (const friends::Friend& f : friends::load_friends(owner)) {
        if (f.user == input) {
            return f.user;
        }
    }
    for (const alias::Entry& a : alias::load_aliases(owner)) {
