    std::string id;
    if (!read_line("Friend: ", id)) {
        return;
    }

    const std::vector<friends::Friend> list = friends::load_friends(owner);

    std::string target = resolve_friend(owner, id);
    // Also accept a 1-based index into the friend list ("friend ID").
    if (target.empty()) {
        char* endp = nullptr;
        const long index = std::strtol(id.c_str(), &endp, 10);
        if (endp != id.c_str() && *endp == '\0' &&
            index >= 1 && index <= static_cast<long>(list.size())) {
            target = list[static_cast<std::size_t>(index - 1)].user;
        }
    }

    if (target.empty()) {
        std::cout << "Friend not found\n";
        return;
    }

    std::cout << "--- Chat with " << alias::display_name(owner, target) << " ---\n";
    chat::run_chat(owner, target);
}

