#ifndef CHATAPP_CONCURRENCY_HPP
#define CHATAPP_CONCURRENCY_HPP

#include <atomic>
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <string>
#include <thread>
#include <vector>

namespace concurrency {

// A small FIFO queue safe for concurrent producers/consumers. Uses a mutex and
// a condition_variable for blocking/timed waits.
template <typename T>
class ThreadSafeQueue {
public:
    void push(const T& value) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            queue_.push(value);
        }
        cv_.notify_one();
    }

    bool try_pop(T& out) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        out = queue_.front();
        queue_.pop();
        return true;
    }

    bool wait_pop(T& out) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !queue_.empty(); });
        out = queue_.front();
        queue_.pop();
        return true;
    }

    bool wait_pop_for(T& out, std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!cv_.wait_for(lock, timeout, [this] { return !queue_.empty(); })) {
            return false;
        }
        out = queue_.front();
        queue_.pop();
        return true;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    mutable std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<T> queue_;
};

// One simulated inbound message from a friend.
struct AutoMessage {
    std::string friendName;
    std::string text;
};

// ---- stdin line reader (lets the UI loop poll for background messages) ----
using InputLine = std::optional<std::string>; // nullopt == EOF

enum class ReadResult { Line, Timeout, Eof };

ThreadSafeQueue<InputLine>& input_queue();

// Spawns a detached thread that forwards every stdin line to `input_queue()`.
void start_input_reader();

// Blocking read; returns Eof when stdin closed.
ReadResult read_input_line(std::string& out);

// Timed read; returns Timeout when nothing arrived in `timeout`.
ReadResult read_input_line_for(std::string& out, std::chrono::milliseconds timeout);

// ---- background friend chat simulation -----------------------------------
class ChatSimulator {
public:
    ChatSimulator() = default;
    ~ChatSimulator();

    ChatSimulator(const ChatSimulator&) = delete;
    ChatSimulator& operator=(const ChatSimulator&) = delete;

    // Spawns one thread per friend; each enqueues a message every
    // [minMs, maxMs] milliseconds.
    void start(const std::vector<std::string>& friends, int minMs = 3000, int maxMs = 6000);

    // Signals every thread to stop and joins them.
    void stop();

    bool try_pop(AutoMessage& out) { return queue_.try_pop(out); }

    ThreadSafeQueue<AutoMessage>& queue() { return queue_; }

private:
    ThreadSafeQueue<AutoMessage> queue_;
    std::vector<std::thread> threads_;
    std::atomic<bool> running_{false};
};

// Runs the simulation without a UI for ~5 seconds and returns exit code 0,
// printing {"processed": N}.
int selftest_concurrency();

} // namespace concurrency

#endif // CHATAPP_CONCURRENCY_HPP

#include "concurrency.hpp"

#include <iostream>
#include <random>

namespace concurrency {

namespace {

ThreadSafeQueue<InputLine>& global_input_queue() {
    static ThreadSafeQueue<InputLine> queue;
    return queue;
}

const char* const kAutoMessages[] = {
    "Hey, are you around?",
    "Just checking in!",
    "Got a minute to chat?",
    "What are you up to?",
    "Long time no talk!",
    "Hope you're doing well.",
    "Did you see the latest news?",
    "Ping!",
};

const int kAutoMessageCount =
    static_cast<int>(sizeof(kAutoMessages) / sizeof(kAutoMessages[0]));

} // namespace

ThreadSafeQueue<InputLine>& input_queue() {
    return global_input_queue();
}

void start_input_reader() {
    std::thread reader([] {
        std::string line;
        while (std::getline(std::cin, line)) {
            if (!line.empty() && line.back() == '\r') {
                line.pop_back();
            }
            input_queue().push(InputLine{line});
        }
        input_queue().push(InputLine{std::nullopt});
    });
    reader.detach();
}

ReadResult read_input_line(std::string& out) {
    return read_input_line_for(out, std::chrono::milliseconds::max());
}

ReadResult read_input_line_for(std::string& out, std::chrono::milliseconds timeout) {
    InputLine value;
    if (!input_queue().wait_pop_for(value, timeout)) {
        return ReadResult::Timeout;
    }
    if (!value.has_value()) {
        return ReadResult::Eof;
    }
    out = *value;
    return ReadResult::Line;
}

ChatSimulator::~ChatSimulator() {
    stop();
}

void ChatSimulator::start(const std::vector<std::string>& friends, int minMs, int maxMs) {
    if (running_.exchange(true)) {
        return; // already running
    }
    if (maxMs < minMs) {
        std::swap(minMs, maxMs);
    }

    for (const std::string& friendName : friends) {
        threads_.emplace_back([this, friendName, minMs, maxMs] {
            std::random_device rd;
            const auto seed = static_cast<std::mt19937::result_type>(rd()) ^
                              static_cast<std::mt19937::result_type>(
                                  std::hash<std::thread::id>{}(std::this_thread::get_id()));
            std::mt19937 rng(seed);
            std::uniform_int_distribution<int> delay(minMs, maxMs);
            std::uniform_int_distribution<int> pick(0, kAutoMessageCount - 1);

            while (running_.load()) {
                const int ms = delay(rng);
                // Sleep in small slices so stop() is responsive.
                for (int slept = 0; slept < ms && running_.load(); slept += 50) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(50));
                }
                if (!running_.load()) {
                    break;
                }

                AutoMessage message;
                message.friendName = friendName;
                message.text = kAutoMessages[pick(rng)];
                queue_.push(message);
            }
        });
    }
}

void ChatSimulator::stop() {
    if (!running_.exchange(false)) {
        return;
    }
    for (std::thread& t : threads_) {
        if (t.joinable()) {
            t.join();
        }
    }
    threads_.clear();
}

int selftest_concurrency() {
    ChatSimulator simulator;
    simulator.start({"alice", "Bob"}, 1000, 2000);

    int processed = 0;
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    while (std::chrono::steady_clock::now() < deadline) {
        AutoMessage message;
        if (simulator.queue().wait_pop_for(message, std::chrono::milliseconds(100))) {
            ++processed;
        }
    }
    simulator.stop();

    std::cout << "{\"processed\": " << processed << "}\n";
    return 0;
}

} // namespace concurrency

