// Appends one complete transcript line atomically: the whole line is written
// with a single O_APPEND write() and flushed with fsync(), so a crash cannot
// leave a partial line (each append is also serialised by a mutex).
bool append_history(const std::string& user, const std::string& friendName,
                    const std::string& sender, const std::string& text) {
    const std::string path = history_path(user, friendName);
    jsonutil::ensure_parent_dir(path);

    const std::string line =
        now_iso8601() + " | " + sender + " | " + text + "\n";

    static std::mutex writeMutex;
    std::lock_guard<std::mutex> lock(writeMutex);

    const int fd = ::open(path.c_str(), O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        return false;
    }

    std::size_t written = 0;
    while (written < line.size()) {
        const ssize_t n = ::write(fd, line.data() + written, line.size() - written);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            ::close(fd);
            return false;
        }
        written += static_cast<std::size_t>(n);
    }

    ::fsync(fd);
    ::close(fd);
    return true;
}

