void run_chat(const std::string& user, const std::string& friendName) {
    const std::vector<std::string> replies = load_bot_replies();
    std::size_t replyIndex = 0;

    // On a terminal the tty echoes typed input; when stdin is a pipe (automation
    // without a pty) we echo it ourselves so the transcript still alternates
    // as `> <message>` / `[Bot] <reply>`.
    const bool echo_input = isatty(STDIN_FILENO) == 0;

    // One background thread per friend pushes simulated inbound messages.
    std::vector<std::string> friendNames;
    for (const friends::Friend& f : friends::load_friends(user)) {
        friendNames.push_back(f.user);
    }
    if (friendNames.empty()) {
        friendNames.push_back(friendName);
    }
    concurrency::ChatSimulator simulator;
    simulator.start(friendNames, 3000, 6000);

    bool promptOpen = false;
    const auto printPrompt = [&promptOpen] {
        std::cout << "> " << std::flush;
        promptOpen = true;
    };

    printPrompt();
    while (true) {
        // 1) Drain any background messages, then reprint the prompt.
        concurrency::AutoMessage message;
        bool printed = false;
        while (simulator.try_pop(message)) {
            if (!printed && promptOpen) {
                std::cout << "\n";
                promptOpen = false;
            }
            std::cout << "[" << alias::display_name(user, message.friendName) << "] "
                      << message.text << "\n";
            append_history(user, message.friendName, message.friendName, message.text);
            printed = true;
        }
        if (printed) {
            printPrompt();
        }

        // 2) Wait briefly for user input so background messages are not starved.
        std::string line;
        const concurrency::ReadResult result =
            concurrency::read_input_line_for(line, std::chrono::milliseconds(200));
        if (result == concurrency::ReadResult::Eof) {
            break;
        }
        if (result == concurrency::ReadResult::Timeout) {
            continue;
        }

        promptOpen = false;
        if (echo_input) {
            std::cout << line << "\n";
        }

        if (line == "/exit" || line == "/back") {
            break;
        }

        if (line == "/history" || line.rfind("/history ", 0) == 0) {
            const std::string arg = trim(line.substr(line.find(' ') == std::string::npos
                                                       ? line.size()
                                                       : line.find(' ') + 1));
            print_history(user, friendName, arg.empty() ? 1 : std::atoi(arg.c_str()));
            printPrompt();
            continue;
        }

        if (line == "/clear") {
            clear_history(user, friendName);
            std::cout << "History cleared\n";
            printPrompt();
            continue;
        }

        if (line.empty()) {
            printPrompt();
            continue;
        }

        // Normal message: persist it, then emit the next bot reply immediately.
        append_history(user, friendName, user, line);

        const std::string reply = replies[replyIndex % replies.size()];
        ++replyIndex;
        append_history(user, friendName, "Bot", reply);

        std::cout << "[Bot] " << reply << "\n";
        printPrompt();
    }

    simulator.stop();
}

