// Unit test for concurrency::ThreadSafeQueue: FIFO ordering and thread safety.
#include "concurrency.hpp"

#include <atomic>
#include <chrono>
#include <iostream>
#include <thread>
#include <vector>

using concurrency::ThreadSafeQueue;

namespace {

int g_failures = 0;

void check(bool condition, const std::string& what) {
    if (!condition) {
        std::cerr << "FAIL: " << what << "\n";
        ++g_failures;
    }
}

} // namespace

int main() {
    // 1) FIFO ordering on a single thread.
    {
        ThreadSafeQueue<int> q;
        for (int i = 0; i < 100; ++i) {
            q.push(i);
        }
        check(q.size() == 100, "size after 100 pushes");

        bool ordered = true;
        for (int i = 0; i < 100; ++i) {
            int value = -1;
            if (!q.try_pop(value) || value != i) {
                ordered = false;
                break;
            }
        }
        check(ordered, "single-thread FIFO order");
        check(q.empty(), "empty after draining");

        int dummy = 0;
        check(!q.try_pop(dummy), "try_pop on empty queue returns false");
    }

    // 2) Multiple producers, one consumer: every item arrives exactly once.
    {
        ThreadSafeQueue<int> q;
        const int producers = 4;
        const int perProducer = 5000;
        const int total = producers * perProducer;

        std::vector<std::thread> threads;
        for (int p = 0; p < producers; ++p) {
            threads.emplace_back([&q, perProducer] {
                for (int i = 0; i < perProducer; ++i) {
                    q.push(i);
                }
            });
        }

        long long sum = 0;
        int count = 0;
        while (count < total) {
            int value = -1;
            q.wait_pop(value);
            sum += value;
            ++count;
        }
        for (std::thread& t : threads) {
            t.join();
        }

        const long long expectedPerProducer =
            static_cast<long long>(perProducer - 1) * perProducer / 2;
        check(count == total, "consumer received every item");
        check(sum == expectedPerProducer * producers, "no loss/duplication in sum");
    }

    // 3) Timed wait returns false promptly when idle.
    {
        ThreadSafeQueue<int> q;
        int value = 0;
        const auto start = std::chrono::steady_clock::now();
        const bool got = q.wait_pop_for(value, std::chrono::milliseconds(50));
        const auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                                 std::chrono::steady_clock::now() - start)
                                 .count();
        check(!got, "timed wait times out on empty queue");
        check(elapsed >= 40, "timed wait actually waited");
    }

    if (g_failures == 0) {
        std::cout << "test_queue: all assertions passed\n";
        return 0;
    }
    std::cerr << "test_queue: " << g_failures << " assertion(s) failed\n";
    return 1;
}

