namespace {

// Returns a strictly increasing ISO 8601 timestamp. If a burst of writes would
// reuse the current second, this waits for the clock to advance so that no two
// log lines ever share a timestamp (the log format keeps second resolution).
std::string next_unique_timestamp() {
    static std::mutex tsMutex;
    static std::string last;

    std::lock_guard<std::mutex> lock(tsMutex);
