namespace {

std::time_t parse_iso8601(const std::string& iso) {
    std::tm tmv{};
    if (strptime(iso.c_str(), "%Y-%m-%dT%H:%M:%S", &tmv) == nullptr) {
        return 0;
    }
    tmv.tm_isdst = -1;
    return std::mktime(&tmv);
}

std::string format_iso8601(std::time_t t) {
    std::tm tmv{};
    localtime_r(&t, &tmv);
    char buffer[32];
    std::strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &tmv);
    return std::string(buffer);
}

// Returns the timestamp of the last non-empty line of `log`, or "".
std::string last_timestamp_in(const std::string& logPath) {
    const std::string content = jsonutil::read_file(logPath);
    std::string lastLine;
    std::istringstream iss(content);
    std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
        if (!line.empty()) {
            lastLine = line;
        }
    }
    if (lastLine.empty()) {
        return std::string();
    }
    const std::size_t sep = lastLine.find(" | ");
    return sep == std::string::npos ? std::string() : lastLine.substr(0, sep);
}

// Returns a strictly increasing ISO 8601 timestamp for `logPath`. Keeps the
// second-resolution log format while guaranteeing that no two lines in the
// same file ever share a timestamp (advancing the clock during bursts instead
// of sleeping, so chat stays responsive).
std::string next_unique_timestamp(const std::string& logPath) {
    static std::mutex tsMutex;
    static std::map<std::string, std::string> lastByFile;

    std::lock_guard<std::mutex> lock(tsMutex);

    auto it = lastByFile.find(logPath);
    if (it == lastByFile.end()) {
        it = lastByFile.emplace(logPath, last_timestamp_in(logPath)).first;
    }

    std::time_t next = parse_iso8601(now_iso8601());
    if (!it->second.empty()) {
        const std::time_t prev = parse_iso8601(it->second);
        if (prev >= next) {
            next = prev + 1;
        }
    }

    it->second = format_iso8601(next);
    return it->second;
}

} // namespace

